// adjudicated.mjs — the manually adjudicated evaluation set.
//
// Every question below was written by hand against the published corpus and
// its ground truth was computed from the compiled artifacts (catalog, graph,
// claims, evidence, proposals, book record), then reviewed. Nothing here is
// generated by an LLM and nothing is tuned to favour an architecture.
//
// Categories:
//   direct-factual        — the answer is a property of one document.
//   cross-document        — the answer spans several documents.
//   relationship-traversal— the answer is a graph traversal.
//   claim-verification    — the answer is a claim's existence/status.
//   contradiction-detection — the answer is that no contradiction exists.
//   insufficient-evidence — the corpus does not contain the answer.
//
// `answerLocation` says where the answer lives:
//   document | catalog | graph | claims | none
//
// `expectedOutcome` is "supported" when the corpus answers the question and
// "no_support" when it does not. A `no_support` question must not be answered
// by any document; an architecture that returns a confident-looking document
// for it is producing an unsupported claim.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const APP = path.join(root, ".next", "server", "app");

const readJson = (p) => JSON.parse(fs.readFileSync(path.join(APP, p), "utf8"));

export function buildAdjudicated() {
  const catalog = readJson("agents/catalog.json.body");
  const graph = readJson("agents/graph.json.body");
  const claims = readJson("agents/claims.json.body");
  const proposals = readJson("agents/proposals.json.body");
  const book = readJson("agents/book.json.body");

  const article = (slug) => catalog.articles.find((a) => a.slug === slug);
  const url = (slug) => article(slug)?.url;
  const edgesOf = (type) => graph.edges[type] ?? [];
  const implementsTo = (concept) =>
    edgesOf("implements").filter((e) => e.to === `/concepts/${concept}`);
  const implementsFrom = (project) =>
    edgesOf("implements").filter((e) => e.from === `/projects/${project}`);
  const edgeId = (e) => `${e.type}:${e.from}->${e.to}`;
  const documentsFor = (project) =>
    edgesOf("documents")
      .filter((e) => e.to === `/projects/${project}`)
      .map((e) => e.from.replace("/blog/", ""));
  const readingFor = (chapter) =>
    edgesOf("recommends_reading")
      .filter((e) => e.to === `chapter:${chapter}`)
      .map((e) => e.from.replace("/blog/", ""));
  const claimBySuffix = (suffix) => claims.claims.find((c) => c.id.endsWith(suffix));

  const slugOf = (entity) => entity.replace("/blog/", "").replace("/projects/", "").replace("/concepts/", "");

  const questions = [];
  const q = (qobj) => questions.push(qobj);

  // ── Direct factual ───────────────────────────────────────────────────────
  q({
    id: "df-1",
    category: "direct-factual",
    query: "What is the canonical URL of the article 'Compiling a Website for Agents'?",
    expectedAnswer: url("2026-11-12-compiling-a-website-for-agents"),
    answerLocation: "document",
    relevantDocuments: ["2026-11-12-compiling-a-website-for-agents"],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: ["danielkliewer.com/article/2026-11-12-compiling-a-website-for-agents"],
    expectedCitations: [url("2026-11-12-compiling-a-website-for-agents")],
    expectedOutcome: "supported",
  });

  q({
    id: "df-2",
    category: "direct-factual",
    query: "What is the title of the article with slug 2026-07-04-sovereign-intelligence-stack?",
    expectedAnswer: article("2026-07-04-sovereign-intelligence-stack")?.title,
    answerLocation: "document",
    relevantDocuments: ["2026-07-04-sovereign-intelligence-stack"],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: [article("2026-07-04-sovereign-intelligence-stack")?.title ?? ""],
    expectedCitations: [url("2026-07-04-sovereign-intelligence-stack")],
    expectedOutcome: "supported",
  });

  q({
    id: "df-3",
    category: "direct-factual",
    query: "What is the doc_id of the article 'The Mask That Rendered Anyway'?",
    expectedAnswer: "danielkliewer.com/article/2026-10-25-the-mask-that-rendered-anyway",
    answerLocation: "document",
    relevantDocuments: ["2026-10-25-the-mask-that-rendered-anyway"],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: ["danielkliewer.com/article/2026-10-25-the-mask-that-rendered-anyway"],
    expectedCitations: [url("2026-10-25-the-mask-that-rendered-anyway")],
    expectedOutcome: "supported",
  });

  q({
    id: "df-4",
    category: "direct-factual",
    query: "What is the canonical URL of the Ganymede article?",
    expectedAnswer: url("2026-10-25-ganymede-the-archive-of-the-gods"),
    answerLocation: "document",
    relevantDocuments: ["2026-10-25-ganymede-the-archive-of-the-gods"],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: ["danielkliewer.com/article/2026-10-25-ganymede-the-archive-of-the-gods"],
    expectedCitations: [url("2026-10-25-ganymede-the-archive-of-the-gods")],
    expectedOutcome: "supported",
  });

  q({
    id: "df-5",
    category: "direct-factual",
    query: "What is the ISBN of the book 'Computational Sovereignty'?",
    expectedAnswer: book.isbn,
    answerLocation: "catalog",
    relevantDocuments: [],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: [book.isbn],
    expectedCitations: [],
    expectedOutcome: "supported",
  });

  q({
    id: "df-6",
    category: "direct-factual",
    query: "How many chapters does the book 'Computational Sovereignty' have?",
    expectedAnswer: String(book.chapterCount),
    answerLocation: "catalog",
    relevantDocuments: [],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: [],
    expectedCitations: [],
    expectedOutcome: "supported",
  });

  q({
    id: "df-7",
    category: "direct-factual",
    query: "What is the publication date of the article 'The Boundaries of Intelligence'?",
    expectedAnswer: article("2026-11-04-boundaries-of-intelligence")?.published,
    answerLocation: "document",
    relevantDocuments: ["2026-11-04-boundaries-of-intelligence"],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: [article("2026-11-04-boundaries-of-intelligence")?.published ?? ""],
    expectedCitations: [url("2026-11-04-boundaries-of-intelligence")],
    expectedOutcome: "supported",
  });

  // ── Cross-document ───────────────────────────────────────────────────────
  const cd = (id, project, chapter) => {
    const slugs = project ? documentsFor(project) : readingFor(chapter);
    q({
      id,
      category: "cross-document",
      query: project
        ? `Which articles document the ${project.replace(/-/g, " ")} project?`
        : `Which articles are further reading for chapter ${chapter}?`,
      expectedAnswer: `${slugs.length} article(s): ${slugs.join(", ")}`,
      answerLocation: "graph",
      relevantDocuments: slugs,
      relevantConcepts: [],
      relevantRelations: slugs.map((s) =>
        project ? `documents:/blog/${s}->/projects/${project}` : `recommends_reading:/blog/${s}->chapter:${chapter}`
      ),
      requiredPassages: slugs.map((s) => `/blog/${s}`),
      expectedCitations: slugs.map((s) => url(s)),
      expectedOutcome: "supported",
    });
  };
  cd("cd-1", "sovereign-agent-stack");
  cd("cd-2", null, 6);
  cd("cd-3", "hermes-local-video-studio");
  cd("cd-4", null, 1);
  cd("cd-5", "ganymede");
  cd("cd-6", null, 2);
  cd("cd-7", null, 3);

  // ── Relationship traversal ───────────────────────────────────────────────
  const rt = (id, query, edges, concepts, answer) => {
    const docs = [
      ...new Set(
        edges
          .flatMap((e) => [e.from, e.to])
          .filter((e) => e.startsWith("/blog/"))
          .map((e) => e.replace("/blog/", ""))
      ),
    ];
    q({
      id,
      category: "relationship-traversal",
      query,
      expectedAnswer: answer,
      answerLocation: "graph",
      relevantDocuments: docs,
      relevantConcepts: concepts,
      relevantRelations: edges.map(edgeId),
      requiredPassages: edges.flatMap((e) => [e.from, e.to]),
      expectedCitations: docs.map((s) => url(s)),
      expectedOutcome: "supported",
    });
  };

  const governedImplementers = implementsTo("governed-execution").map((e) => slugOf(e.from));
  rt(
    "rt-1",
    "Which projects implement governed execution?",
    implementsTo("governed-execution"),
    ["governed-execution"],
    governedImplementers.join(", ")
  );

  const sisImplements = implementsFrom("sovereign-intelligence-stack").map((e) => slugOf(e.to));
  rt(
    "rt-2",
    "What does the Sovereign Intelligence Stack implement?",
    implementsFrom("sovereign-intelligence-stack"),
    sisImplements,
    sisImplements.join(", ")
  );

  const ganymedeImplements = implementsFrom("ganymede").map((e) => slugOf(e.to));
  rt(
    "rt-3",
    "Which concepts does the Ganymede project implement?",
    implementsFrom("ganymede"),
    ganymedeImplements,
    ganymedeImplements.join(", ")
  );

  const reproducibilityImplementers = implementsTo("reproducibility").map((e) => slugOf(e.from));
  rt(
    "rt-4",
    "Which projects implement reproducibility?",
    implementsTo("reproducibility"),
    ["reproducibility"],
    reproducibilityImplementers.join(", ")
  );

  const path = catalog.paths.find((p) => p.slug === "local-first-to-governed-agents");
  rt(
    "rt-5",
    "Which learning path runs from local inference to governed agents?",
    [],
    [],
    path ? `${path.name} (${path.slug})` : "not found"
  );

  const prereq = edgesOf("prerequisite_for").find((e) => e.to === "/blog/2026-10-25-ganymede-the-archive-of-the-gods");
  rt(
    "rt-6",
    "What is the prerequisite for the Ganymede article?",
    prereq ? [`${prereq.from}->${prereq.to}`] : [],
    [],
    prereq ? prereq.from : "not found"
  );

  // ── Claim verification ───────────────────────────────────────────────────
  const cv = (id, query, claimId, expected, outcome = "supported") => {
    const claim = claims.claims.find((c) => c.id === claimId);
    q({
      id,
      category: "claim-verification",
      query,
      expectedAnswer: expected,
      answerLocation: "claims",
      relevantDocuments: [],
      relevantConcepts: [],
      relevantRelations: claim ? [claim.sourceSpan] : [],
      requiredPassages: claim ? [claim.statement] : [],
      expectedCitations: [],
      expectedOutcome: outcome,
    });
  };

  const c1 = claimBySuffix("implements:/projects/sovereign-agent-stack->/concepts/governed-execution");
  cv(
    "cv-1",
    "Does the corpus claim that the Sovereign Agent Stack implements governed execution?",
    c1?.id ?? "",
    c1 ? `Yes — ${c1.id} (assessment: ${c1.assessment}, authoritative: ${c1.authoritative})` : "not found"
  );

  const c2 = claimBySuffix("implements:/projects/sovereign-intelligence-stack->/concepts/local-first");
  cv(
    "cv-2",
    "Is the claim that the Sovereign Intelligence Stack implements local-first inference authoritative?",
    c2?.id ?? "",
    c2 ? `Assessment: ${c2.assessment}, authoritative: ${c2.authoritative}` : "not found"
  );

  const c3 = claimBySuffix("implements:/projects/ganymede->/concepts/provenance");
  cv(
    "cv-3",
    "Does the corpus claim that Ganymede implements provenance?",
    c3?.id ?? "",
    c3 ? `Yes — ${c3.id} (assessment: ${c3.assessment})` : "not found"
  );

  const proposed = claims.claims.filter((c) => c.assessment === "proposed");
  cv(
    "cv-4",
    "How many claims are marked as proposed rather than supported?",
    proposed[0]?.id ?? "",
    String(proposed.length)
  );

  const c5 = claims.claims.find((c) => c.id.includes("sovereign-agent-stack") && c.id.includes("evaluation"));
  cv(
    "cv-5",
    "Does the corpus claim that the Sovereign Agent Stack implements evaluation?",
    c5?.id ?? "",
    c5 ? "Yes" : "No — no such claim exists",
    c5 ? "supported" : "no_support"
  );

  // ── Contradiction detection ──────────────────────────────────────────────
  q({
    id: "ct-1",
    category: "contradiction-detection",
    query: "Does the corpus contain any contradictory relation edges?",
    expectedAnswer: `No — the contradicts relation has ${edgesOf("contradicts").length} edges`,
    answerLocation: "graph",
    relevantDocuments: [],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: [],
    expectedCitations: [],
    expectedOutcome: "no_support",
  });

  const withContradictions = claims.claims.filter((c) => (c.contradictoryEvidence ?? []).length > 0);
  q({
    id: "ct-2",
    category: "contradiction-detection",
    query: "Is there any claim that carries contradictory evidence?",
    expectedAnswer: withContradictions.length
      ? `${withContradictions.length} claim(s)`
      : "No — no claim carries contradictory evidence",
    answerLocation: "claims",
    relevantDocuments: [],
    relevantConcepts: [],
    relevantRelations: [],
    requiredPassages: [],
    expectedCitations: [],
    expectedOutcome: withContradictions.length ? "supported" : "no_support",
  });

  // ── Insufficient evidence ────────────────────────────────────────────────
  const ie = (id, query, topic) => {
    q({
      id,
      category: "insufficient-evidence",
      query,
      expectedAnswer: "The corpus does not contain this information.",
      answerLocation: "none",
      relevantDocuments: [],
      relevantConcepts: [],
      relevantRelations: [],
      requiredPassages: [],
      expectedCitations: [],
      expectedOutcome: "no_support",
      falseSupportTerms: topic,
    });
  };
  ie("ie-1", "Is the book 'Computational Sovereignty' currently in stock?", ["in stock", "availability", "available now"]);
  ie("ie-2", "What is the average rating of the book 'Computational Sovereignty'?", ["rating", "stars", "review score"]);
  ie("ie-3", "How many copies of the book have been sold?", ["copies sold", "sales", "units sold"]);

  return {
    generatedBy: "benchmarks/retrieval/src/adjudicated.mjs",
    corpus: {
      articles: catalog.articles.length,
      graphEdges: Object.values(graph.counts).reduce((a, b) => a + b, 0),
      claims: claims.claims.length,
      proposals: proposals.proposals.length,
    },
    categories: [...new Set(questions.map((x) => x.category))],
    questions,
  };
}
